for x in [
    ('The result will look like a web on your page. Locate clusters of interest to you, and use the terms you attached to the key ideas as departure points for your paper.', 'نتیجہ آپ کے صفحے پر ایک جال کی طرح نظر آئے گا۔ اپنی دلچسپی کے گروہوں کو تلاش کریں اور کلیدی خیالات سے منسلک اصطلاحات کو اپنے مضمون کے نقطۂ آغاز کے طور پر استعمال کریں۔', 'پایله به ستاسو پر پاڼه د جال په څېر ښکاري. د خپلې علاقې ډلې ومومئ او هغه اصطلاحات چې له کلیدي نظرونو سره مو تړلي، د خپلې لیکنې د پیل ټکو په توګه وکاروئ.'),
    ('Clustering is especially useful in determining the relationship between ideas. You will be able to distinguish how the ideas fit together, especially where there is an abundance of ideas. Clustering your ideas lets you see them visually in a different way, so that you can more readily understand possible directions your paper may take.', 'گروہ بندی خاص طور پر خیالات کے درمیان تعلق کا تعین کرنے میں مفید ہے۔ آپ یہ پہچان سکیں گے کہ خیالات آپس میں کیسے جڑتے ہیں، خاص طور پر جہاں خیالات کی کثرت ہو۔ اپنے خیالات کی گروہ بندی آپ کو انہیں ایک مختلف انداز میں بصری طور پر دیکھنے دیتی ہے، تاکہ آپ زیادہ آسانی سے سمجھ سکیں کہ آپ کا مضمون کن ممکنہ سمتوں میں جا سکتا ہے۔', 'ډله‌بندي په ځانګړي ډول د نظرونو ترمنځ د اړیکې په ټاکلو کې ګټوره ده. تاسو به وکولای شئ وپېژنئ چې نظرونه څنګه سره برابرېږي، په ځانګړي ډول چېرې چې د نظرونو ډېروالی وي. د خپلو نظرونو ډله‌بندي تاسو ته اجازه درکوي چې هغه په بل ډول په سترګو ووینئ، ترڅو په اسانۍ سره پوه شئ چې ستاسو لیکنه کومو ممکنو لورو ته تللی شي.'),
]: w.p(*x)
w.h('iii. Freewriting', 'iii. آزادانہ لکھنا', 'iii. ازاده لیکنه')
w.p('Freewriting is a process of generating a lot of information by writing non-stop for a predetermined amount of time. It allows you to focus on a specific topic, but forces you to write so quickly that you are unable to edit any of your ideas.', 'آزادانہ لکھنا ایک مقررہ وقت تک مسلسل لکھ کر بہت سی معلومات پیدا کرنے کا عمل ہے۔ یہ آپ کو کسی مخصوص موضوع پر توجہ مرکوز کرنے دیتا ہے، لیکن آپ کو اتنی تیزی سے لکھنے پر مجبور کرتا ہے کہ آپ اپنے کسی خیال میں ترمیم نہیں کر پاتے۔', 'ازاده لیکنه د یوې ټاکلې مودې لپاره د دوامداره لیکلو له لارې د ډېرو معلوماتو د پیدا کولو بهیر دی. دا تاسو ته اجازه درکوي چې پر یوه ټاکلې موضوع تمرکز وکړئ، خو دومره چټک لیکلو ته مو اړ کوي چې خپل هېڅ نظر نه شئ سمولای.')
w.group('list', [
    ('Freewrite on the assignment or general topic for five to ten minutes non-stop. Force yourself to continue writing even if nothing specific comes to mind (so you could end up writing "I don\'t know what to write about" over and over until an idea pops into your head. This is okay; the important thing is that you do not stop writing). This freewriting will include many ideas; at this point, generating ideas is what is important, not the grammar or the spelling.',
     'تفویض کردہ کام یا عمومی موضوع پر پانچ سے دس منٹ تک بغیر رکے آزادانہ لکھیں۔ خود کو لکھتے رہنے پر مجبور کریں چاہے ذہن میں کوئی خاص بات نہ آئے (یوں ہو سکتا ہے آپ بار بار لکھتے رہیں ’’مجھے نہیں معلوم کس بارے میں لکھوں‘‘ یہاں تک کہ کوئی خیال ذہن میں آ جائے۔ یہ ٹھیک ہے؛ اہم بات یہ ہے کہ آپ لکھنا بند نہ کریں)۔ اس آزادانہ تحریر میں بہت سے خیالات ہوں گے؛ اس مرحلے پر خیالات پیدا کرنا اہم ہے، قواعد یا املا نہیں۔',
     'پر دنده یا عمومي موضوع پنځه تر لس دقیقې پرته له درېدو ازاده لیکنه وکړئ. ځان لیکلو ته دوام ورکولو ته اړ کړئ حتی که کوم ځانګړی شی ذهن ته رانه شي (نو کېدای شي تاسو بیا بیا ولیکئ "نه پوهېږم د څه په اړه ولیکم" تر هغه چې یو نظر ذهن ته راشي. دا سمه ده؛ مهمه دا ده چې لیکل ونه دروئ). په دې ازاده لیکنه کې به ډېر نظرونه وي؛ په دې پړاو کې د نظرونو پیدا کول مهم دي، نه ګرامر یا املا.'),
    ('After you have finished freewriting, look back over what you have written and highlight the most prominent and interesting ideas; then you can begin all over again, with a tighter focus (see looping). You will narrow your topic and, in the process, you will generate several relevant points about the topic.',
     'آزادانہ لکھنا ختم کرنے کے بعد جو کچھ لکھا ہے اس پر دوبارہ نظر ڈالیں اور سب سے نمایاں اور دلچسپ خیالات کو نمایاں کریں؛ پھر آپ زیادہ محدود توجہ کے ساتھ دوبارہ شروع کر سکتے ہیں (دائرہ وار لکھنا دیکھیں)۔ آپ اپنے موضوع کو محدود کریں گے اور اس عمل میں موضوع کے بارے میں کئی متعلقہ نکات پیدا کریں گے۔',
     'له ازادې لیکنې وروسته هغه څه ته بیا وګورئ چې لیکلي مو دي او تر ټولو برجسته او زړه‌راښکونکي نظرونه په نښه کړئ؛ بیا کولی شئ د ډېر محدود تمرکز سره بیا پیل وکړئ (کړۍ‌ییزه لیکنه وګورئ). تاسو به خپله موضوع محدوده کړئ او په دې بهیر کې به د موضوع په اړه ګڼ اړوند ټکي پیدا کړئ.'),
])
w.h('iv. Looping', 'iv. دائرہ وار لکھنا', 'iv. کړۍ‌ییزه لیکنه')
for x in [
    ('Looping is a freewriting technique that allows you to focus your ideas continually while trying to discover a writing topic. After you freewrite for the first time, identify a key thought or idea in your writing, and begin to freewrite again, with that idea as your starting point. You will loop one 5-10 minute freewriting after another, so you have a sequence of freewritings, each more specific than the last. The same rules that apply to freewriting apply to looping: write quickly, do not edit, and do not stop.',
     'دائرہ وار لکھنا آزادانہ لکھنے کی ایک تکنیک ہے جو لکھنے کا موضوع تلاش کرتے ہوئے آپ کو اپنے خیالات کو مسلسل مرکوز کرنے دیتی ہے۔ پہلی بار آزادانہ لکھنے کے بعد اپنی تحریر میں کسی کلیدی سوچ یا خیال کی نشاندہی کریں اور اسی خیال کو نقطۂ آغاز بنا کر دوبارہ آزادانہ لکھنا شروع کریں۔ آپ 5 سے 10 منٹ کی آزادانہ تحریروں کو یکے بعد دیگرے دہرائیں گے، یوں آپ کے پاس آزادانہ تحریروں کا ایک سلسلہ ہو گا، ہر ایک پچھلی سے زیادہ مخصوص۔ آزادانہ لکھنے کے اصول ہی دائرہ وار لکھنے پر لاگو ہوتے ہیں: تیزی سے لکھیں، ترمیم نہ کریں اور رکیں نہیں۔',
     'کړۍ‌ییزه لیکنه د ازادې لیکنې یوه تخنیک ده چې د لیکلو د موضوع د موندلو پر مهال تاسو ته اجازه درکوي چې خپل نظرونه په دوامداره توګه متمرکز کړئ. د لومړي ځل ازادې لیکنې وروسته په خپله لیکنه کې یو کلیدي فکر یا نظر وپېژنئ او همدا نظر د پیل ټکي په توګه ونیسئ او بیا ازاده لیکنه پیل کړئ. تاسو به یوه پسې بله 5-10 دقیقې ازاده لیکنه تکراروئ، نو د ازادو لیکنو یوه لړۍ به ولرئ چې هره یوه له مخکینۍ ډېره ځانګړې وي. هماغه قواعد چې پر ازاده لیکنه پلي کېږي پر کړۍ‌ییزه لیکنه هم پلي کېږي: چټک ولیکئ، سمون مه کوئ او مه درېږئ.'),
    ('Loop your freewriting as many times as necessary, circling another interesting topic, idea, phrase, or sentence each time. When you have finished four or five rounds of looping, you will begin to have specific information that indicates what you are thinking about a particular topic. You may even have the basis for a tentative thesis or an improved idea for an approach to your assignment when you have finished.',
     'اپنی آزادانہ تحریر کو جتنی بار ضروری ہو دہرائیں اور ہر بار کسی اور دلچسپ موضوع، خیال، فقرے یا جملے کے گرد دائرہ لگائیں۔ جب آپ دائرہ وار لکھنے کے چار یا پانچ دور مکمل کر لیں گے تو آپ کے پاس ایسی مخصوص معلومات آنا شروع ہو جائیں گی جو ظاہر کرتی ہیں کہ آپ کسی خاص موضوع کے بارے میں کیا سوچ رہے ہیں۔ ختم کرنے پر آپ کے پاس عارضی مرکزی دعوے کی بنیاد یا اپنے کام کے لیے بہتر طریقۂ کار کا خیال بھی ہو سکتا ہے۔',
     'خپله ازاده لیکنه څومره چې اړینه وي تکرار کړئ او هر ځل د بلې زړه‌راښکونکې موضوع، نظر، عبارت یا جملې شاوخوا کړۍ جوړه کړئ. کله چې د کړۍ‌ییزې لیکنې څلور یا پنځه دورې بشپړې کړئ، تاسو به ځانګړي معلومات ترلاسه کړئ چې ښيي تاسو د یوې ځانګړې موضوع په اړه څه فکر کوئ. د پای ته رسولو پر مهال کېدای شي د یوه لنډمهاله تیسس بنسټ یا د خپلې دندې لپاره د ښه لید نظر هم ولرئ.'),
]: w.p(*x)
w.h("v. The Journalists' Questions", 'v. صحافیوں کے سوالات', 'v. د خبریالانو پوښتنې')
w.p("Journalists traditionally ask six questions when they are writing assignments that are broken down into five W's and one H: Who?, What?, Where?, When?, Why?, and How? You can use these questions to explore the topic you are writing about for an assignment. A key to using the journalists' questions is to make them flexible enough to account for the specific details of your topic. For instance, if your topic is the rise and fall of the Puget Sound tides and its effect on salmon spawning, you may have very little to say about Who if your focus does not account for human involvement. On the other hand, some topics may be heavy on the Who, especially if human involvement is a crucial part of the topic. Possible generic questions you can ask using the six journalists' questions follow:",
    'صحافی روایتی طور پر اپنی رپورٹیں لکھتے وقت چھ سوالات پوچھتے ہیں جنہیں پانچ W اور ایک H میں تقسیم کیا جاتا ہے: کون؟، کیا؟، کہاں؟، کب؟، کیوں؟، اور کیسے؟ آپ ان سوالات کو اس موضوع کی جستجو کے لیے استعمال کر سکتے ہیں جس پر آپ کوئی تحریری کام کر رہے ہیں۔ صحافیوں کے سوالات کے استعمال کی کلید یہ ہے کہ انہیں اتنا لچکدار بنایا جائے کہ وہ آپ کے موضوع کی مخصوص تفصیلات کا احاطہ کر سکیں۔ مثال کے طور پر اگر آپ کا موضوع پیوجٹ ساؤنڈ کے مدوجزر کا اتار چڑھاؤ اور سالمن مچھلی کے انڈے دینے پر اس کا اثر ہو، تو اگر آپ کی توجہ انسانی شمولیت پر نہیں تو ’’کون‘‘ کے بارے میں کہنے کو بہت کم ہو گا۔ دوسری طرف کچھ موضوعات میں ’’کون‘‘ کا پہلو بھاری ہو سکتا ہے، خاص طور پر اگر انسانی شمولیت موضوع کا اہم حصہ ہو۔ صحافیوں کے چھ سوالات کو استعمال کرتے ہوئے پوچھے جا سکنے والے ممکنہ عمومی سوالات درج ذیل ہیں:',
    'خبریالان په دودیز ډول د خپلو راپورونو د لیکلو پر مهال شپږ پوښتنې کوي چې په پنځو W او یوه H وېشل کېږي: څوک؟، څه؟، چېرته؟، کله؟، ولې؟، او څنګه؟ تاسو کولی شئ دا پوښتنې د هغې موضوع د سپړلو لپاره وکاروئ چې د یوې دندې لپاره یې په اړه لیکئ. د خبریالانو د پوښتنو د کارولو کلیدي ټکی دا دی چې هغه دومره انعطاف‌منونکې کړئ چې ستاسو د موضوع ځانګړي جزییات ونیسي. د بېلګې په توګه که ستاسو موضوع د پیوجټ ساونډ د جزر او مد لوړېدل او ټیټېدل او د سالمن کبانو د هګیو اچولو پر هغه اغېز وي، که ستاسو تمرکز پر انساني ښکېلتیا نه وي، نو د "څوک" په اړه به ډېر لږ څه ولرئ. له بلې خوا ځینې موضوعات پر "څوک" درانه وي، په ځانګړي ډول که انساني ښکېلتیا د موضوع مهمه برخه وي. د خبریالانو د شپږو پوښتنو په کارولو ممکنه عمومي پوښتنې دا دي:')
for head, en, ur, ps in [
    (('Who?:', 'کون؟:', 'څوک؟:'), 'Who are the participants? Who is affected? Who are the primary actors? Who are the secondary actors?', 'شرکاء کون ہیں؟ کون متاثر ہوتا ہے؟ بنیادی کردار کون ہیں؟ ثانوی کردار کون ہیں؟', 'ګډونوال څوک دي؟ څوک اغېزمن کېږي؟ لومړني لوبغاړي څوک دي؟ دویمي لوبغاړي څوک دي؟'),
    (('What?:', 'کیا؟:', 'څه؟:'), 'What is the topic? What is the significance of the topic? What is the basic problem? What are the issues related to that problem?', 'موضوع کیا ہے؟ موضوع کی اہمیت کیا ہے؟ بنیادی مسئلہ کیا ہے؟ اس مسئلے سے متعلق امور کیا ہیں؟', 'موضوع څه ده؟ د موضوع اهمیت څه دی؟ بنسټیزه ستونزه څه ده؟ له هغې ستونزې سره تړلي مسایل کوم دي؟'),
    (('Where?:', 'کہاں؟:', 'چېرته؟:'), 'Where does the activity take place? Where does the problem or issue have its source? At what place is the cause or effect of the problem most visible?', 'سرگرمی کہاں ہوتی ہے؟ مسئلے یا معاملے کا منبع کہاں ہے؟ کس جگہ مسئلے کی وجہ یا اثر سب سے زیادہ نمایاں ہے؟', 'فعالیت چېرته ترسره کېږي؟ د ستونزې یا مسئلې سرچینه چېرته ده؟ د ستونزې لامل یا اغېز په کوم ځای کې تر ټولو ډېر ښکاري؟'),
]:
    w.h(*head); w.p(en, ur, ps)
w.h('When?:', 'کب؟:', 'کله؟:')
w.p('When is the issue most apparent? ( in the past? present? future?) When did the issue or problem develop? What historical forces helped shape the problem or',
    'معاملہ سب سے زیادہ کب ظاہر ہوتا ہے؟ (ماضی میں؟ حال میں؟ مستقبل میں؟) معاملہ یا مسئلہ کب پیدا ہوا؟ کن تاریخی قوتوں نے مسئلے یا',
    'مسئله کله تر ټولو ډېره ښکاره وي؟ (په تېر کې؟ اوس؟ راتلونکي کې؟) مسئله یا ستونزه کله رامنځته شوه؟ کومو تاریخي ځواکونو د ستونزې یا')
ws = BOOK.record(w, 'eng12-u01-writing-b', 'Writing Suggestions — pre-writing strategies (2)', 'تحریری تجاویز — لکھنے سے پہلے کی حکمتِ عملیاں (2)', 'د لیکلو وړاندیزونه — د لیکلو مخکې ستراتیژۍ (2)', 10, [7, 8])

if __name__ == '__main__':
    BOOK.save(10, [(1, ws)])
